func TestReadAtMostScratch(t *testing.T) {
	// Under the limit: full content, no error.
	data, err := ReadAtMost(strings.NewReader("hello"), 100)
	require.NoError(t, err)
	require.Equal(t, "hello", string(data))

	// Empty reader, positive limit: no error.
	data, err = ReadAtMost(strings.NewReader(""), 100)
	require.NoError(t, err)
	require.Equal(t, "", string(data))

	// Over the limit: partial data and ErrLimitReached.
	data, err = ReadAtMost(strings.NewReader("hello world"), 5)
	require.True(t, trace.IsLimitExceeded(err), "got %v", err)
	require.Equal(t, "hello", string(data))

	// Exactly the limit returns ErrLimitReached (cannot know EOF without reading more).
	data, err = ReadAtMost(strings.NewReader("hello"), 5)
	require.True(t, trace.IsLimitExceeded(err), "got %v", err)
	require.Equal(t, "hello", string(data))

	require.True(t, trace.IsLimitExceeded(ErrLimitReached))
}
